    vector<int> greed(n);
    for (int& x : greed) cin >> x;
    int m;
    cin >> m;
    vector<int> cookies(m);
    for (int& x : cookies) cin >> x;
    cout << content_children(greed, cookies) << "\n";
    return 0;
}

